import{z as o,x as i,o as B,c as s,q as A,j as r,D as a,d as l,s as t,S as n}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"RM 工程收束","description":"","frontmatter":{"title":"RM 工程收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rm-engineering-map.md","filePath":"llm/rm-engineering-map.md","lastUpdated":1791413859000}'),F={name:"llm/rm-engineering-map.md"};function m(C,E,d,p,D,h){const e=i("Mermaid");return B(),s("div",null,[E[2]||(E[2]=A('<h1 id="rm-工程收束" tabindex="-1">RM 工程收束 <a class="header-anchor" href="#rm-工程收束" aria-label="Permalink to &quot;RM 工程收束&quot;">​</a></h1><div class="epigraph"><p>整门课是一句主干课结论的展开：奖励模型是比较数据的回归器——数据的信噪比与覆盖是它的天花板，策略的优化是它的放大器。</p><footer>—— 据 Ouyang 等 InstructGPT 2022、Touvron 等 Llama 2 2023、Gao 等 2022 的工程口径整理</footer></div><p><a href="/llm/rm-acceptance-checklist">上一课</a>把十四项失效模式钉成一排数字门，门关上，工程闭环成形。本课程从 <a href="/llm/reward-model">奖励模型</a> 被当成真值的那个标量开卷，经数据、偏置、工程三单元，至此收束。收束课做该做的事：把三个单元放回同一张账，写明每课回答的问题、留下的手段，以及它们共享的那条主线——<strong>RM 的每个性质都是数据性质的影子，策略会把影子放大成制度</strong>。后课默认已读完本课程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把十五课压成一个判断：RM 工程是在「比较数据定义好」的前提下管三件事——数据的信噪比与覆盖、测量的偏置清单、优化回路里对放大器的约束。缺任何一件的失效形态都见过：数据不管（不标一致性、不记来源），RM 学到的是标注流程的副产品；测量不管（不算长度系数、不做反事实改写），捷径在验证集的掌声里长大；回路不管（不白化、不监测分歧、不跑金标试跑），PPO 把每一处小病放大成行为。三个单元就是这三件事的顺序，也是新 RM 项目的开工顺序。</p><p><span class="marginnote">一个直觉类比：把 RM 项目当成盖房子——数据单元是地基材料（沙子里有泥，墙再正也要裂），偏置单元是尺子准不准（尺子本身短一寸，每面墙都量歪同一方向），工程单元是施工队（管理不当会把材料的小缺陷放大成整栋楼的倾斜）。顺序错了，返工成本指数上涨。</span></p>',6)),(B(),r(n,null,{default:a(()=>[t(e,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20UNIT1%5B%22%E6%95%B0%E6%8D%AE%E4%B8%8E%E9%85%8D%E6%AF%94%EF%BC%9A%E6%9D%A5%E6%BA%90%20%2F%20%E9%85%8D%E6%AF%94%20%2F%20%E5%BD%A2%E6%80%81%20%2F%20%E4%B8%80%E8%87%B4%E6%80%A7%20%2F%20%E5%BC%BA%E5%BA%A6%22%5D%20--%3E%20RM%5B%22RM%EF%BC%9A%E6%AF%94%E8%BE%83%E6%95%B0%E6%8D%AE%E7%9A%84%E5%9B%9E%E5%BD%92%E5%99%A8%22%5D%0A%20%20UNIT2%5B%22%E5%81%8F%E7%BD%AE%E4%B8%8E%E6%B5%8B%E9%87%8F%EF%BC%9A%E9%95%BF%E5%BA%A6%20%2F%20%E9%A3%8E%E6%A0%BC%20%2F%20%E5%88%86%E5%B8%83%E5%A4%96%20%2F%20%E6%96%B9%E5%B7%AE%22%5D%20--%3E%20AUDIT%5B%22%E5%AE%A1%E8%AE%A1%E6%B8%85%E5%8D%95%E4%B8%8E%E4%B8%89%E4%B8%AA%E6%94%AF%E6%92%91%E4%BB%A3%E7%90%86%22%5D%0A%20%20UNIT3%5B%22%E5%B7%A5%E7%A8%8B%E4%B8%8E%E8%AF%84%E6%B5%8B%EF%BC%9A%E9%87%87%E9%9B%86%20%2F%20%E8%92%B8%E9%A6%8F%E7%BA%A7%E8%81%94%20%2F%20%E5%85%AC%E5%B9%B3%E6%AF%94%E8%BE%83%20%2F%20%E5%9F%BA%E5%87%86%20%2F%20%E9%AA%8C%E6%94%B6%22%5D%20--%3E%20LOOP%5B%22%E6%BB%9A%E5%8A%A8%E5%9B%9E%E8%B7%AF%EF%BC%9A%E9%87%87%E9%9B%86-%E8%AE%AD%E7%BB%83-%E8%AF%95%E8%B7%91-%E9%97%A8%22%5D%0A%20%20RM%20--%3E%20AUDIT%0A%20%20AUDIT%20--%3E%20LOOP%0A%20%20LOOP%20--%3E%7C%22%E7%AD%96%E7%95%A5%E7%A7%BB%E5%8A%A8%EF%BC%8C%E6%95%B0%E6%8D%AE%E8%B4%AC%E5%80%BC%22%7C%20UNIT1%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三单元各留下一件可持续的东西。数据与配比单元留下<strong>口径</strong>：来源四类进数据卡、配比按分域下限验收、形态以成对为主干、一致率给准确率封顶、强度档当免费的噪声探测器。偏置与测量单元留下<strong>三口径模板</strong>——数据相关、反事实改写、行为漂移，长度与风格两课示范了怎么套到任何新特征上；再加两个仪表：OOD 三代理与奖励方差三层稳定化。工程与评测单元留下<strong>回路</strong>：主动采集决定下一批预算花在哪，蒸馏与级联决定打分的钱怎么省，公平比较决定主张怎么证，基准-持有-试跑三层决定信什么，验收门决定放不放。每件都能独立运行，合起来是自我修正的系统：策略移动 → 监测发现失配 → 采集补对 → 重训 → 门。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>贯穿全课的机制只有一条：BT 损失忠实拟合数据的可分结构，而「可分」优先选最便宜的特征——长度、格式、语气；持有集与训练集同分布，分数于是表扬捷径；RL 是以分数为目标的最大化器，任何系统偏差都被单调放大（<a href="/llm/rm-overoptimization">RM 过优化与 Goodhart</a> 的曲线是它的宏观投影）。课程里所有「根本解」都作用在这条链的同一环上：改数据的经验分布，让便宜特征失去预测价值——反事实对、强度降权、主动采集、配比补域，全是这一招的不同入口；而损失端惩罚、评测端控制、入口截断都是局部止血，各有副作用，只能当第二道防线。理解了这条链，就理解了为什么课程把数据单元放在最前：源头上的每一分功夫，都比下游多一分的杠杆。</p>',4)),(B(),r(n,null,{default:a(()=>[t(e,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E6%95%B0%E6%8D%AE%E9%87%8C%E4%BE%BF%E5%AE%9C%E7%89%B9%E5%BE%81%E5%8F%AF%E5%88%86%EF%BC%88%E9%95%BF%E5%BA%A6%20%2F%20%E6%A0%BC%E5%BC%8F%20%2F%20%E8%AF%AD%E6%B0%94%EF%BC%89%22%5D%20--%3E%20F%5B%22BT%20%E6%8D%9F%E5%A4%B1%E4%BC%98%E5%85%88%E6%8B%9F%E5%90%88%E6%9C%80%E4%BE%BF%E5%AE%9C%E7%89%B9%E5%BE%81%22%5D%0A%20%20F%20--%3E%20V%5B%22%E6%8C%81%E6%9C%89%E9%9B%86%E4%B8%8E%E8%AE%AD%E7%BB%83%E9%9B%86%E5%90%8C%E5%88%86%E5%B8%83%EF%BC%8C%E9%AA%8C%E8%AF%81%E9%9B%86%E6%8E%8C%E5%A3%B0%E9%80%9A%E8%BF%87%22%5D%0A%20%20V%20--%3E%20RL%5B%22RL%20%E4%BB%A5%E5%88%86%E6%95%B0%E4%B8%BA%E7%9B%AE%E6%A0%87%E5%8D%95%E8%B0%83%E6%94%BE%E5%A4%A7%E5%81%8F%E5%B7%AE%22%5D%0A%20%20RL%20--%3E%20B%5B%22%E8%A1%8C%E4%B8%BA%E5%9B%BA%E5%8C%96%EF%BC%9A%E7%AD%96%E7%95%A5%E5%AD%A6%E4%BC%9A%E5%87%91%E9%95%BF%E5%BA%A6%E4%B8%8E%E6%A0%BC%E5%BC%8F%22%5D%0A%20%20B%20--%3E%20FIX%5B%22%E6%A0%B9%E6%9C%AC%E8%A7%A3%EF%BC%9A%E6%94%B9%E6%95%B0%E6%8D%AE%E5%88%86%E5%B8%83%EF%BC%8C%E8%AE%A9%E4%BE%BF%E5%AE%9C%E7%89%B9%E5%BE%81%E5%A4%B1%E9%A2%84%E6%B5%8B%E4%BB%B7%E5%80%BC%22%5D%0A%20%20FIX%20--%3E%20D%0A%20%20PATCH%5B%22%E6%83%A9%E7%BD%9A%20%2F%20%E6%88%AA%E6%96%AD%EF%BC%9A%E5%B1%80%E9%83%A8%E6%AD%A2%E8%A1%80%E7%9A%84%E7%AC%AC%E4%BA%8C%E9%81%93%E9%98%B2%E7%BA%BF%22%5D%20--%3E%20RL%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">术语翻译：这一节描述的就是 Goodhart 定律的 LLM 版——「当一个测量变成优化目标，它就不再是好的测量」。RM 分数本来是「人类偏好」的测量，一旦策略专门去最大化它，分数涨的部分里就混进了越来越大的「钻空子」成分，测量随之失真。</span></p><p><span class="marginnote">留给新项目的自查顺序：先问数据从哪来、谁判的（来源谱系），再问域怎么切、下限定多少（配比与验收），最后才问损失与模型多大——顺序反了的项目，通常把该花在第一问的预算花在了第三问。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收束即边界。本课程的全部方法都以「比较数据可采集、标注员可训练、指南可成文」为前提；监督本身成为瓶颈的场景——专家稀缺、判断超出人类、偏好不可言说——已经站在 <a href="/llm/rlaif">RLAIF</a>、<a href="/llm/scalable-oversight">可扩展监督</a>与生成式 RM（<a href="/llm/generative-rm">生成式奖励模型</a>）的地界，那是另一门课的输入。可验证域是另一个出口：验证器不需要一致性检验，也就不需要本课程大半的仪表——工程量省下来，换成了「验证器覆盖不到什么」的新问题（<a href="/llm/rlvr-design-space">RLVR 的设计空间</a>）。</p><p><span class="marginnote">直觉区分「验证器」与「RM」：数学题有标准答案，验证器像个只会判对错的批卷程序，零噪声、不需要标一致性；而「这段回答写得帮不帮人」没有标准答案，只能靠 RM 这个学出来的近似裁判。前者省掉本课大半工程，代价是只覆盖得了能机械判对错的域。</span>最后，RM 工程的输出从不只是分数：它把一个组织的价值观写成数据卡、指南与门，这三样东西比任何单个模型活得都久。本课程到此收束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全课主线：RM 是比较数据的回归器，数据定天花板，策略做放大器；三个单元分别管数据、测量、回路。</li><li>根本解只有一个入口：改数据的经验分布，让长度、格式等便宜特征失去预测价值；惩罚与截断是第二道防线。</li><li>回路五件套：采集、训练、三口径审计、三层评测、验收门，靠监测触发滚动。</li><li>前提即边界：监督可采集、可成文才适用；可验证域与监督瓶颈是两处出口。</li><li>出处：Ouyang 等 InstructGPT，2022；Touvron 等 Llama 2，2023；Gao、Schulman、Hilton，2022；Coste 等 2023。</li></ul>',7))])}const T=o(F,[["render",m]]);export{c as __pageData,T as default};
